+const EMPTY_DELEGATION_RESULT = "(The delegated agent completed without producing text.)";
+
+type DelegationResult = {
+  content: string;
+  isError: boolean;
+};
+
+type DelegationInput = {
+  agentId: string;
+  instructions: string;
+};
+
+function parseDelegationInput(input: unknown): DelegationInput | null {
+  if (!input || typeof input !== "object") return null;
+
+  const { agent_id, instructions } = input as Record<string, unknown>;
+  if (typeof agent_id !== "string" || typeof instructions !== "string") {
+    return null;
+  }
+
+  return { agentId: agent_id, instructions };
+}
+
+function createToolUseId(response: ProviderResponse): string {
+  return response.toolUseId || `delegate_task_${crypto.randomUUID()}`;
+}
+
+function toolResultPayload(toolUseId: string, result: DelegationResult) {
+  return {
+    type: "tool_result",
+    is_error: result.isError,
+    content: result.content,
+    tool_use_id: toolUseId,
+  };
+}
+
+function toolUseStreamResponse(
+  agentId: string,
+  request: ChatRequest,
+  toolUseId: string,
+  input: unknown,
+): StreamResponse {
+  return {
+    type: "claude_json",
+    data: {
+      type: "assistant",
+      message: {
+        role: "assistant",
+        content: [{
+          type: "tool_use",
+          id: toolUseId,
+          name: "delegate_task",
+          input,
+        }],
+      },
+      session_id: request.sessionId,
+      agent_id: agentId,
+    },
+  };
+}
+
+function toolResultStreamResponse(
+  request: ChatRequest,
+  toolUseId: string,
+  result: DelegationResult,
+): StreamResponse {
+  return {
+    type: "claude_json",
+    data: {
+      type: "user",
+      message: {
+        role: "user",
+        content: [toolResultPayload(toolUseId, result)],
+      },
+      session_id: request.sessionId,
+    },
+  };
+}
