+/**
+ * Runs an agent and, when it requests delegate_task, runs the requested child
+ * agent before invoking this agent again with the matching tool_result.
+ */
+async function runAgent(
+  agentId: string,
+  message: string,
+  request: ChatRequest,
+  abortController: AbortController,
+  debugMode: boolean,
+  ancestry: string[],
+  emit: (response: StreamResponse) => void,
+): Promise<DelegationResult> {
+  const provider = globalRegistry.getProviderForAgent(agentId);
+  const agentConfig = globalRegistry.getAgent(agentId);
+
+  if (!provider || !agentConfig) {
+    return {
+      isError: true,
+      content: `Agent '${agentId}' not found or provider not available`,
+    };
+  }
+
+  const context: ProviderChatRequest["context"] = [];
+  let accumulatedText = "";
+
+  while (!abortController.signal.aborted) {
+    let shouldResume = false;
+
+    try {
+      const providerRequest: ProviderChatRequest = {
+        message,
+        sessionId: request.sessionId,
+        requestId: request.requestId,
+        workingDirectory: request.workingDirectory || agentConfig.workingDirectory,
+        ...(context.length ? { context } : {}),
+      };
+
+      for await (const response of provider.executeChat(providerRequest, {
+        debugMode,
+        abortController,
+        temperature: agentConfig.config?.temperature,
+        maxTokens: agentConfig.config?.maxTokens,
+      })) {
+        const chatRoomMessage = createChatRoomMessage(response, agentId);
+        if (chatRoomMessage) {
+          emit({
+            type: "claude_json",
+            data: {
+              type: "chat_room_message",
+              message: chatRoomMessage,
+              session_id: request.sessionId,
+            },
+          });
+        }
+
+        if (response.type === "text") {
+          const text = response.content || "";
+          accumulatedText += text;
+          emit({
+            type: "claude_json",
+            data: {
+              type: "assistant",
+              content: text,
+              model: response.metadata?.model,
+            },
+          });
+          continue;
+        }
+
+        if (response.type === "error") {
+          return { isError: true, content: response.error || "Agent execution failed" };
+        }
+
+        if (response.type !== "tool_use" || response.toolName !== "delegate_task") {
+          if (response.type === "done") break;
+          continue;
+        }
+
+        const toolUseId = createToolUseId(response);
+        emit(toolUseStreamResponse(agentId, request, toolUseId, response.toolInput));
+
+        const delegation = parseDelegationInput(response.toolInput);
+        let childResult: DelegationResult;
+
+        if (!delegation) {
+          childResult = {
+            isError: true,
+            content: "delegate_task requires string agent_id and instructions",
+          };
+        } else if (ancestry.includes(delegation.agentId)) {
+          childResult = {
+            isError: true,
+            content: `Circular delegation detected for agent '${delegation.agentId}'`,
+          };
+          emit({ type: "error", error: childResult.content });
+        } else if (!globalRegistry.getAgent(delegation.agentId) || !globalRegistry.getProviderForAgent(delegation.agentId)) {
+          childResult = {
+            isError: true,
+            content: `Agent '${delegation.agentId}' not found or provider not available`,
+          };
+          emit({ type: "error", error: childResult.content });
+        } else {
+          childResult = await runAgent(
+            delegation.agentId,
+            delegation.instructions,
+            request,
+            abortController,
+            debugMode,
+            [...ancestry, delegation.agentId],
+            emit,
+          );
+        }
+
+        emit(toolResultStreamResponse(request, toolUseId, childResult));
+        context.push({
+          role: "user",
+          content: JSON.stringify(toolResultPayload(toolUseId, childResult)),
+        });
+        shouldResume = true;
+        break;
+      }
+    } catch (error) {
+      return {
+        isError: true,
+        content: error instanceof Error ? error.message : String(error),
+      };
+    }
+
+    if (!shouldResume) {
+      return {
+        isError: false,
+        content: accumulatedText || EMPTY_DELEGATION_RESULT,
+      };
+    }
+  }
+
+  return { isError: true, content: "Request aborted" };
+}
